---@param suitEffectData table {effectNum, desc, activation, lastActiveIndex(可选)}
function UICultivateEquipIntroductionDescNodeMB:RefreshUI(suitEffectData, position, lastActiveIndex, iShowCanActive)
    local activation = checkNumber(suitEffectData.activation)
    --local color = COLOR_LIST[activation]
    local isActivation = activation > 0
    local status = isActivation and 1 or 2
    self.SuitEffectNumText.Status = status
    self.SuitEffectNumText.textComp.text = localize("【_num_件效果】", {_num_ = suitEffectData.effectNum})

    local isShowExclusiveText = iShowCanActive == true and lastActiveIndex ~= nil and lastActiveIndex >= position
    KTool.SetActive(self.ExclusiveText.gameObject, isShowExclusiveText)

    self.DescText.Status = status
    self.DescText.textComp.text = suitEffectData.desc

    self:FixCellSize(self.controller.gameObject)
end

function UICultivateEquipIntroductionDescNodeMB:FixCellSize(gameObject)
    local rt = KTool.GetComponent(gameObject, RectTransformType)
    CS.UnityEngine.UI.LayoutRebuilder.ForceRebuildLayoutImmediate(rt)
end
